import sys
from typing import List

class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        count = {}
        n = len(nums)

        # Iterate through all subarrays of size k
        for i in range(n - k + 1):
            # Get unique elements in the current subarray
            # Using set ensures we count the subarray occurrence only once per number
            unique_elements = set(nums[i : i + k])
            for x in unique_elements:
                count[x] = count.get(x, 0) + 1

        max_val = -1
        for x, c in count.items():
            if c == 1:
                if x > max_val:
                    max_val = x

        return max_val

if __name__ == "__main__":
    try:
        # Read input from stdin using input()
        # We need to read two lines: the array and k.
        # We use a loop to skip potential empty lines to be robust.
        lines = []
        while len(lines) < 2:
            try:
                line = input().strip()
                if line:
                    lines.append(line)
            except EOFError:
                break

        if len(lines) >= 2:
            # Parse nums
            # Remove brackets and split by comma
            nums_str = lines[0].replace('[', '').replace(']', '')
            nums = [int(x.strip()) for x in nums_str.split(',') if x.strip()]

            # Parse k
            k = int(lines[1])

            solution = Solution()
            result = solution.largestInteger(nums, k)
            print(result)
    except Exception:
        pass
